arguments.command:
$filePath = 'X:\code\copilot-worktrees\P08\cirvine-msft-friendly-robot\assets\stats.txt'

# Read the file as raw bytes to check line endings
$bytes = [System.IO.File]::ReadAllBytes($filePath)
$content = [System.IO.File]::ReadAllText($filePath)
$lines = $content -split "`n"

# Remove the last empty element if file ends with newline
if ($lines[-1] -eq '') { $lines = $lines[0..($lines.Length - 2)] }

Write-Host "=== VERIFICATION RESULTS ==="
Write-Host ""

# 1. Line count
Write-Host "1. Line Count: $(if ($lines.Count -eq 12) { '✓ PASS' } else { '✗ FAIL' }) (Expected: 12, Got: $($lines.Count))"

# 2. Line lengths
$lengthPass = $true
$lengthIssues = @()
for ($i = 0; $i -lt $lines.Count; $i++) {
    $len = $lines[$i].Length
    if ($len -lt 20 -or $len -gt 48) {
        $lengthPass = $false
        $lengthIssues += "Line $($i+1): $len chars"
    }
}
Write-Host "2. Line Lengths (20-48 chars): $(if ($lengthPass) { '✓ PASS' } else { '✗ FAIL' })"
if (-not $lengthPass) {
    foreach ($issue in $lengthIssues) {
        Write-Host "   - $issue"
    }
}

# 3. No trailing whitespace
$trailingPass = $true
$trailingIssues = @()
for ($i = 0; $i -lt $lines.Count; $i++) {
    if ($lines[$i] -match '\s$') {
        $trailingPass = $false
        $trailingIssues += "Line $($i+1) has trailing whitespace"
    }
}
Write-Host "3. No Trailing Whitespace: $(if ($trailingPass) { '✓ PASS' } else { '✗ FAIL' })"
if (-not $trailingPass) {
    foreach ($issue in $trailingIssues) {
        Write-Host "   - $issue"
    }
}

# 4. Only allowed characters
$allowedChars = '[A-Z0-9 +|/\\\_*\.#\(\):=\-]'
$charPass = $true
$charIssues = @()
for ($i = 0; $i -lt $lines.Count; $i++) {
    if ($lines[$i] -match "[^A-Z0-9 +|/\\\_*\.#\(\):=\-]") {
        $charPass = $false
        $charIssues += "Line $($i+1) has disallowed characters"
    }
}
Write-Host "4. Only Allowed Characters: $(if ($charPass) { '✓ PASS' } else { '✗ FAIL' })"
if (-not $charPass) {
    foreach ($issue in $charIssues) {
        Write-Host "   - $issue"
    }
}

# 5. Contains STATS
$hasStats = $content -contains 'STATS' -or ($content.IndexOf('STATS') -ge 0)
Write-Host "5. Contains 'STATS': $(if ($hasStats) { '✓ PASS' } else { '✗ FAIL' })"

# 6. Ends with exactly one newline (LF)
$endsWithLF = $bytes[-1] -eq 10  # LF is byte 10
$hasDoubleLF = $bytes.Length -ge 2 -and $bytes[-2] -eq 10 -and $bytes[-1] -eq 10
Write-Host "6. Ends with Exactly One LF: $(if ($endsWithLF -and -not $hasDoubleLF) { '✓ PASS' } else { '✗ FAIL' })"
if (-not ($endsWithLF -and -not $hasDoubleLF)) {
    Write-Host "   Last 3 bytes: $(if ($bytes.Length -ge 3) { "$([int]$bytes[-3]), " })$([int]$bytes[-2]), $([int]$bytes[-1])"
}

# 7. LF line endings (not CRLF)
$hasCRLF = $bytes -contains 13  # CR is byte 13
Write-Host "7. LF Endings (No CRLF): $(if (-not $hasCRLF) { '✓ PASS' } else { '✗ FAIL' })"

Write-Host ""
Write-Host "=== FILE CONTENT ==="
Write-Host ($content)

